example_queries:
# Packages with the most security advisories
PREFIX eco: <https://w3id.org/rete/ecosystems#>
SELECT ?ecosystem ?pkg (COUNT(?a) AS ?advisories) WHERE {
  ?a a eco:Advisory ; eco:affectsPackage ?p .
  ?p eco:ecosystem ?ecosystem ; eco:name ?pkg .
} GROUP BY ?ecosystem ?pkg ORDER BY DESC(?advisories) LIMIT 20

# Advisories with the widest blast radius
PREFIX eco: <https://w3id.org/rete/ecosystems#>
SELECT ?title ?severity ?cvss ?blast WHERE {
  ?a a eco:Advisory ; eco:name ?title ; eco:blastRadius ?blast .
  OPTIONAL { ?a eco:severity ?severity }
  OPTIONAL { ?a eco:cvssScore ?cvss }
} ORDER BY DESC(?blast) LIMIT 20

# Best-funded Open Collective collectives, and how many projects each funds
PREFIX eco: <https://w3id.org/rete/ecosystems#>
SELECT ?collective ?name ?donations (COUNT(?p) AS ?projects) WHERE {
  ?collective a eco:Collective ; eco:name ?name ; eco:totalDonations ?donations ; eco:fundsProject ?p .
} GROUP BY ?collective ?name ?donations ORDER BY DESC(?donations) LIMIT 20

# GitHub Sponsors accounts with the most active sponsors
PREFIX eco: <https://w3id.org/rete/ecosystems#>
SELECT ?account ?login ?active ?kind WHERE {
  ?account a eco:SponsorAccount ; eco:login ?login ; eco:activeSponsorsCount ?active .
  OPTIONAL { ?account eco:agentKind ?kind }
} ORDER BY DESC(?active) LIMIT 20

# Open Sustainable Technology projects per field
PREFIX eco: <https://w3id.org/rete/ecosystems#>
SELECT ?field (COUNT(?p) AS ?projects) WHERE {
  ?p eco:inField ?field .
} GROUP BY ?field ORDER BY DESC(?projects)

# Awesome lists per primary programming language
PREFIX eco: <https://w3id.org/rete/ecosystems#>
SELECT ?language (COUNT(?list) AS ?lists) WHERE {
  ?list a eco:AwesomeList ; eco:programmingLanguage ?language .
} GROUP BY ?language ORDER BY DESC(?lists) LIMIT 20

# Awesome topics and the topics they relate to
PREFIX eco: <https://w3id.org/rete/ecosystems#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
SELECT ?label (COUNT(?other) AS ?related) WHERE {
  ?t a eco:Topic ; skos:prefLabel ?label ; skos:related ?other .
} GROUP BY ?label ORDER BY DESC(?related) LIMIT 20
